cd "$BENCHMARK_WORKSPACE" && cat > /tmp/test_arm.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <capstone/capstone.h>

int main() {
    csh handle;
    cs_insn *insn;
    size_t count;

    // Test with ARM mode
    uint8_t code[] = {0x00, 0x00, 0x00, 0x00};

    if (cs_open(CS_ARCH_ARM, CS_MODE_ARM, &handle) != CS_ERR_OK) {
        printf("Failed to initialize capstone\n");
        return 1;
    }

    cs_option(handle, CS_OPT_DETAIL, CS_OPT_ON);

    count = cs_disasm(handle, code, sizeof(code), 0x1000, 0, &insn);

    printf("Disassembled %zu instructions\n", count);

    if (count > 0) {
        for (size_t i = 0; i < count; i++) {
            printf("0x%"PRIx64":\t%s\t\t%s\n", 
                   insn[i].address, insn[i].mnemonic, insn[i].op_str);
        }
        cs_free(insn, count);
    }

    cs_close(&handle);
    return 0;
}
EOF
